import{c as t,Q as a,j as r,m as s}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Andrej Karpathy on Claude Fable 5 — major-version-bump-deserving step change","description":"","frontmatter":{"url":"https://x.com/karpathy/status/2064409694761054332","title":"Andrej Karpathy on Claude Fable 5 — major-version-bump-deserving step change","author":"Andrej Karpathy","archived":"2026-06-15T00:00:00.000Z","handle":"@karpathy","published":"2026-06-09T00:00:00.000Z","score":"7.0/10","stats":"25,281 likes · 2,376 retweets","tags":["fable-5","qualitative-review","long-problem-solving","capability-jump"],"type":"tweet"},"headers":[],"relativePath":"research/tweets/2026-06-09-@karpathy-054332.md","filePath":"research/tweets/2026-06-09-@karpathy-054332.md","lastUpdated":1785909234000}'),n={name:"research/tweets/2026-06-09-@karpathy-054332.md"};function o(d,e,i,h,l,p){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="andrej-karpathy-on-claude-fable-5-—-major-version-bump-deserving-step-change" tabindex="-1">Andrej Karpathy on Claude Fable 5 — major-version-bump-deserving step change <a class="header-anchor" href="#andrej-karpathy-on-claude-fable-5-—-major-version-bump-deserving-step-change" aria-label="Permalink to &quot;Andrej Karpathy on Claude Fable 5 — major-version-bump-deserving step change&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/karpathy/status/2064409694761054332" target="_blank" rel="noreferrer">https://x.com/karpathy/status/2064409694761054332</a><strong>作者</strong>：Andrej Karpathy（@karpathy） <strong>發布日期</strong>：2026-06-09 <strong>收錄日期</strong>：2026-06-15 <strong>類型</strong>：tweet <strong>統計</strong>：25,281 likes · 2,376 retweets</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>This is a super exciting release - Claude Fable 5 is the same underlying model as Mythos but with added safeguards. The benchmarks are great and it&#39;s SOTA on everything by a margin but I&#39;ll add that <em>qualitatively</em> also, this is a major-version-bump-deserving step change forward (imo of the same order as Claude 4.5 was in November), peaking especially for long problem-solving sessions on very difficult problems. You can give it a lot more ambitious tasks than what you&#39;re used to, the model &quot;gets it&quot; more, requires less hand-holding and steering, and feels like working with a more senior engineer.</p><p>Free until June 22 (in Pro/Max plans, counts as ~2x Opus usage), then moves to usage credits. Highly recommend trying it before then if you haven&#39;t.</p><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>7/10</td><td>「給更多野心任務、少手持」可直接調整 Claude Code 使用姿勢，但無操作步驟</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>Karpathy 獨立定性比較（同 Claude 4.5 級別跳躍），但屬評論非新框架</td></tr><tr><td>C. 證據品質 (20%)</td><td>7/10</td><td>頂級研究者第一手使用印象，定性比較有說服力但缺量化</td></tr><tr><td>D. 技術深度 (15%)</td><td>6/10</td><td>描述體驗感受為主，未深入技術細節</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>「senior engineer feel」適用所有使用 Fable 5 的場景</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.0/10</strong></td><td>A×0.3+B×0.2+C×0.2+D×0.15+E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Skip <strong>理由</strong>：評論性文字，信息已被更具體的使用指南（daniel_mac8）覆蓋</p>',10)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
